await expect(
        captureCertifiedProjectFactsV2(fixture.input, fixture.ports)
      ).rejects.toMatchObject({
        code: 'PROJECT_CONTEXT_SOURCE_STATE_DRIFT',
        retryable: true,
      });

await expect(
      new FileCertifiedProjectFactsStore(root, { logger: { info() {}, warn() {} } }).put(artifact)
    ).rejects.toThrow(/failed strict readiness/);

await expect(
      store.acquireRunLease({
        preparationId: preparation.preparationId,
        runId: 'run-b',
        expectedCertificationBindingHash: artifact.certificationBindingHash,
      })
    ).rejects.toBeInstanceOf(ProjectFactsLeaseConflictError);

await expect(
      replay.completeRunLease({
        preparationId: preparation.preparationId,
        runId: 'run-crash',
        expectedCertificationBindingHash: artifact.certificationBindingHash,
      })
    ).resolves.toMatchObject({ status: 'completed' });

await expect(
      store.open(artifact.artifactId, artifact.certificationBindingHash)
    ).resolves.toMatchObject({
      certificationBindingHash: sealedBase.certificationBindingHash,
      facts: { inventory: { fileCount: artifact.facts.inventory.fileCount } },
    });

expect(() =>
      buildColdStartWorkflowPlan({
        intent: createInternalColdStartIntent(),
        projectRoot: path.join(fixture.controlRoot, 'AlembicCore'),
        dataRoot: fixture.dataRoot,
      })
    ).toThrow(/full-reset cleanup root must not point at a ProjectScope member folder/)

expect(() =>
        assertSemanticDispositionReviewDurableAttestationV5({
          attestation: candidate as unknown as typeof attestation,
          expectedTrustPolicy: gateway.trustPolicy,
        })
      ).toThrow()

expect(() =>
      createInductionReceiptV1({
        populationHash: 'sha256:population',
        clusterHash: 'sha256:cluster-one',
        clusterId: 'cluster-one',
        observationIds: ['o1'],
        mode: 'recurring',
        currentAnalysisFixpointHash: `sha256:${'b'.repeat(64)}`,
        hypotheses: [{ hypothesisId: 'h1', statement: 'not recurring', premiseFactIds: ['f1'] }],
      })
    ).toThrow('INDUCTION_RECURRING_DENOMINATOR_INSUFFICIENT');

expect(() =>
      createInductionReceiptV1({
        populationHash: 'sha256:population',
        clusterHash: 'sha256:cluster-zero',
        clusterId: 'cluster-zero',
        observationIds: ['o2', 'o3'],
        mode: 'recurring',
        currentAnalysisFixpointHash: `sha256:${'b'.repeat(64)}`,
        hypotheses: [],
        zeroHypothesisReason: 'refuted',
        zeroHypothesisReviewReceiptId: 'review:zero',
      })
    ).toThrow('INDUCTION_ZERO_REASON_REQUIRED');

